import { describe, expect, it } from 'vitest';

interface LineItem { unitPriceMinor: number; quantity: number; }
export function subtotalMinor(items: readonly LineItem[]): number {
  return items.reduce((sum, item) => {
    if (!Number.isSafeInteger(item.unitPriceMinor) || item.unitPriceMinor < 0 ||
        !Number.isSafeInteger(item.quantity) || item.quantity < 0) {
      throw new Error('Invalid line item');
    }
    return sum + item.unitPriceMinor * item.quantity;
  }, 0);
}

describe('subtotalMinor unit tests', () => {
  it('adds integer minor units without floating point prices', () => {
    expect(subtotalMinor([{ unitPriceMinor: 1299, quantity: 2 }])).toBe(2598);
  });
  it('returns zero for an empty cart', () => {
    expect(subtotalMinor([])).toBe(0);
  });
  it('rejects a negative quantity', () => {
    expect(() => subtotalMinor([{ unitPriceMinor: 100, quantity: -1 }])).toThrow();
  });
});
