// Simplified server-side TypeScript authorization example.
// The verified identity and memberships must come from trusted server middleware.
interface VerifiedPrincipal {
  userId: string;
  tenantIds: readonly string[];
  permissions: readonly string[];
}
interface Invoice { id: string; tenantId: string; totalMinor: number; }

export function canReadInvoice(
  principal: VerifiedPrincipal,
  invoice: Invoice
): boolean {
  return principal.tenantIds.includes(invoice.tenantId) &&
    principal.permissions.includes('invoice:read');
}

const principal: VerifiedPrincipal = {
  userId: 'U-1', tenantIds: ['TENANT-A'], permissions: ['invoice:read']
};
const a: Invoice = { id: 'INV-A', tenantId: 'TENANT-A', totalMinor: 1250 };
const b: Invoice = { id: 'INV-B', tenantId: 'TENANT-B', totalMinor: 1250 };
console.assert(canReadInvoice(principal, a) === true);
console.assert(canReadInvoice(principal, b) === false);
