import { HttpErrorResponse, HttpInterceptorFn } from '@angular/common/http';
import { inject, Injectable } from '@angular/core';
import { catchError, throwError } from 'rxjs';

@Injectable({ providedIn: 'root' })
export class SafeDiagnostics {
  record(event: { method: string; path: string; status: number; requestId: string | null }): void {
    // Forward to an approved redacted telemetry service in production.
    console.warn('HTTP failure', event);
  }
}

export const diagnosticInterceptor: HttpInterceptorFn = (req, next) => {
  const diagnostics = inject(SafeDiagnostics);
  return next(req).pipe(
    catchError((error: unknown) => {
      if (error instanceof HttpErrorResponse && error.status === 401) {
        const safePath = new URL(req.url, 'https://example.invalid').pathname;
        diagnostics.record({
          method: req.method,
          path: safePath,
          status: error.status,
          requestId: error.headers.get('X-Request-ID')
        });
      }
      return throwError(() => error); // Do not hide the original error.
    })
  );
};
// Configure via provideHttpClient(withInterceptors([diagnosticInterceptor])).
// Never record access tokens, cookies, query strings or sensitive response bodies.
